### 1. Shared constant: `EXIT_SHIP_MAX_SPEED = 2` in `@shared/interaction.ts` (next to `ENTER_SHIP_MAX_SPEED`).

### 2. Server: `app/src/server/shard/shard.ts`

Add a pure helper (exported, unit-testable):

```ts
/**
 * TASK-105: the disembark gate for one ship state.
 * 'docked' — padId is set: the pad plane path (byte-for-byte identical to TASK-31).
 * 'landed' — resting on the surface: flight regime 'surface' (regime machine
 *    — landable planet is implied) and total velocity under the shared egress cap.
 * 'not-landed' — everything else (airborne, in space, or moving ≥ the cap on the ground).
 */
export function canExitShip(state: {
  padId?: string | null;
  regime: string;
  speed: number;
}): 'docked' | 'landed' | 'not-landed' {
  if (state.padId) return 'docked';
  if (state.regime === 'surface' && state.speed < EXIT_SHIP_MAX_SPEED) return 'landed';
  return 'not-landed';
}
```

