```ts
import { EXIT_SHIP_MAX_SPEED } from '@shared/interaction';

/**
 * Exit-ship (egress) state (TASK-105) — …
 */

type CanExitListener = (value: boolean) => void;

/**
 * Pure predicate: the self ship is LANDED on the surface and can be exited
 * (the off-pad half of the egress gate). The wire flight regime must be
 * 'surface' (the regime machine rests it on a landable planet's terrain)
 * AND the total speed must be below the shared egress cap (the SAME
 * EXIT_SHIP_MAX_SPEED the server's gate reads). The PAD-docked case is the
 * docked store's job (isDocked — wire regime 'docked' + padId); a ship
 * resting at the home dock has wire regime 'docked' and never reads as
 * 'surface', so it stays out of this signal (its egress path is unchanged).
 */
export function canExitLanded(flightRegime: string, speed: number): boolean {
  return flightRegime === 'surface' && speed < EXIT_SHIP_MAX_SPEED;
}

const listeners = new Set<CanExitListener>();
let current = false;

/** Set the can-exit state; emitted only on change. */
export function setCanExitShip(value: boolean): void {
  if (value === current) return;
  current = value;
  for (const fn of [...listeners]) fn(value);
}

/** The current can-exit state (false when the ship is not a landed surface ship). */
export function canExitShip(): boolean {
  return current;
}

/** Subscribe to changes. Calls fn(currentValue) immediately; returns the unsubscribe. */
export function canExitShipSubscribe(fn: CanExitListener): () => void {
  listeners.add(fn);
  fn(current);
  return () => {
    listeners.delete(fn);
  };
}

/** Test helper: clear subscribers + reset the store to false (mirrors __resetDockedIndicator). */
export function __resetCanExitShip(): void {
  listeners.clear();
  current = false;
}
```

